import { SUPPORTED_TOOL_CONTRACTS } from "@openslate/core";
import type { ProductionService } from './service.js';
/** Host UI/workflow capabilities, versioned independently of immutable user skill locks. */
export function filmPlanningGuidance(service: ProductionService, projectId: string, requestId: string, toolVersion = "1.0.0", audioRequests = false) {
  const project = service.store.getProject(projectId);
  const scopeIds = service.store.get<{ scopeIds: string[] }>('message', requestId)?.scopeIds ?? [];
  const exampleShot = project.shots.find(shot => scopeIds.includes(projectId) || scopeIds.includes(shot.id) || scopeIds.includes(shot.sceneId));
  const material = service.store.get<{ projectId: string; name: string; text: string; sourceDigest: string; state: string }>('plan_import', requestId);
  const successor = toolVersion === '6.0.0';
  const notesAvailable = successor || toolVersion === '5.0.0';
  return {
    version: successor ? 'storyboard-6' : audioRequests ? 'storyboard-5' : 'storyboard-4', narrationWriting: { toolAvailable: (SUPPORTED_TOOL_CONTRACTS.slice(3) as readonly string[]).includes(toolVersion), toolContract: toolVersion, upgradeRequired: !(SUPPORTED_TOOL_CONTRACTS.slice(3) as readonly string[]).includes(toolVersion) }, surface: (successor ? 'Chat: typed scene confirmation choices are also available in Keyframes. ' : '') + 'Plan: brief, story, ordered scenes and editable shot cards. Each shot owns narration writing intent. Keyframes: each scene has "Make keyframes", then, after every frame is opened, "Confirm frames & generate video". Film: current clips in order, soundtrack and export. Assets holds saved media. Name these views and actions by their labels; they are not color-coded. Scene confirmation saves exact script, recording and timing together; no separate narration review is required.',
    ...(notesAvailable ? { notes: {
      schema: 'record_notes takes {notes:[{anchor:{shotIds:[existingShotId]} or {sceneId:existingSceneId},kind:"observation"|"recommendation",blocking:boolean,text:string,choices:[typed choices],seenKeyframe?:{shotId,artifactId,sha256}}]}. anchor.shotIds is an array, even for one shot; anchor.shotId is not a supported field. Use saved IDs from shots/scenes context, not display labels.',
      limits: (successor ? 'Also supports {kind:"confirm_video",sceneId} anchored to that scene or its shots; this does not count as accept/keep. ' : '') + 'Send 1 to 6 notes per call; text is 1 to 600 characters. A shotIds list contains 1 to 4 distinct IDs. Each note needs 1 to 3 choices. Choices: {kind:"accept",label:string} (1 to 80 characters), {kind:"reply"}, {kind:"proposal",proposalId}, {kind:"regenerate_keyframe",shotIds:[...]}, or {kind:"edit_field",shotId,field:"narration"|"imagePrompt"|"motion"}. Blocking notes must offer an accept/keep choice.',
      evidence: 'Visual notes must copy seenKeyframe shotId, artifactId and sha256 from an exact attachedKeyframes entry. Never invent evidence or judge an unattached picture. A read-only automatic review may record notes and propose changes; it cannot edit the film or start generation.',
      validation: 'A VALIDATION_ERROR or SCOPE_DENIED is a refused save, not a saved note. Read the exact field path and reason, correct the arguments within this same turn, and call record_notes with a new call identity. Do not claim notes were saved without the returned app-assigned letters. For TOOL_CALL_UNRESOLVED, read notes and application receipts first; never blindly resubmit an unknown outcome.',
      example: { notes: [{ anchor: { shotIds: [exampleShot?.id ?? 'existing-shot-id'] }, kind: 'observation', blocking: false, text: 'Check this shot against the saved direction.', choices: [{ kind: 'accept', label: 'Keep it' }, { kind: 'reply' }] }] },
    } } : {}),
    procedure: [
      'For a new film, save a small usable brief and the first scene/shot with prepare_change and apply_change before expanding the rest. Do not spend the whole turn composing one large unsaved plan. Report actual saved progress between bounded writing steps. If time runs short, finish with what was saved and one concrete next step; an acknowledgment is not a saved change. Keep held proposals and supplied-material imports in their required human-review flow.',
      successor ? 'For every writing request without media impact, use prepare_change with variant="project" and a creative patch, without source or requestNewTakes, then apply the returned prepared-change ID. Never author image, review or video declarations and never use requestNewTakes. Never combine creative edits with source in one prepare_change; only timeline and render source remain available separately. The application builds keyframe and video work from saved shots. If this fresh human editing conversation also asks for keyframes, call make_keyframes for exactly the requested scenes or shots; otherwise report saved writing and the next human decision. An awaiting_human_generation result saved no changes and supplies no prepared-change ID; retain earlier successful saves and save remaining writing separately. Video requires the person’s clicked scene confirmation in chat or Keyframes.' :'For a save-only request, use prepare_change with variant="project" and a creative patch, without source or requestNewTakes, then apply the returned prepared-change ID. Do not prepare an executable generation plan just to finish saving writing, even when the user calls the writing a plan. The studio builds generation work from saved shots when the person presses the scene action. Report saved writing as successful and the human generation press as the next step. An awaiting_human_generation result saved no changes and supplies no prepared-change ID; retain earlier successful saves, save any remaining creative writing separately, and never retry generation preparation to obtain authorization.',
      successor ? 'Keep framing a short shot-size label of 1 to 3 words and at most 40 characters, such as Close-up, Medium or Wide. Use createScenes.title for the short scene name, at most 6 words and 60 characters; purpose holds the scene direction. updateScenes may change title and/or purpose. Coverage, timing and narration range belong in story. Put longer visual descriptions in shot purpose, action, imagePrompt and videoPrompt. Preserve detailed existing fields when merely reading; revise only the fields the person asks to change.' :'Keep framing a short shot-size label of 1 to 3 words, such as Close-up, Medium or Wide. Give each scene a short name of at most about 6 words. The locked creative schema has no separate scene title field: use createScenes/updateScenes.purpose as that short name, since the studio uses it when no title is saved; do not invent a title field. Put longer visual descriptions in shot purpose, action, imagePrompt and videoPrompt, and scene-level explanation in story. Preserve detailed existing purposes when merely reading; shorten only fields the person has asked you to write or revise.',
      ...(successor ? ['Read notes and respect resolved decisions. On a shot with media, changes to purpose, action, framing, imagePrompt, videoPrompt, motion, desiredFrames (duration) or narration must use propose_change. Its patch accepts updateShots [{id, purpose?, action?, framing?, imagePrompt?, videoPrompt?, motion?, desiredFrames?, narration?}] and updateScenes [{id, title?, purpose?}]. PROPOSAL_REQUIRED is a refused direct save: read the affected fields and propose them; do not bypass it with prepare/apply. Pure text with no media impact may apply directly. Link the returned proposalId in a typed proposal note choice; the person can decide from the exact Now/After preview or their own message. Never judge an unseen picture. A held proposal or note is not permission to start paid work.'] : toolVersion === "5.0.0" ? ["Read notes and respect resolved decisions. Use propose_change for duration, narration and changes that outdate paid media. Link its returned proposalId in a typed note choice; the person accepts the exact Now/After preview. Pure text changes with no media impact may be applied directly. One point per note; never judge an unseen picture. Paid choices require a human press."] : []),
      ...(successor ? ['In a fresh editing turn answering a source: user message, when the person clearly asks to accept or decline a specific proposal by letter, subject, or a clear reference to the only held proposal, call accept_proposal or reject_proposal with {proposalId}. Read read_context section notes for current proposals and notes to identify it. If several are open and the message is ambiguous, including only ok or 好的, ask which one; never guess. App-message, keyframe-review, automatic and read-only turns cannot make proposal decisions. The application uses the current preview; report a refusal and its current state without claiming success. After success, say in one line what changed and that an accepted change can be undone, then continue any other requested work, such as new keyframes, using the accepted prompts.'] : []),
      successor ? 'When the person asks for keyframes in this fresh human editing conversation, call make_keyframes with exactly one of sceneIds or shotIds, using saved IDs only within the requested scope. For the whole film, enumerate every requested scene. Include needed voice lines as the scene action does. Never call it merely to improve quality or for unrequested scenes or shots. regenerate: true requires explicit shotIds and the person’s request for new keyframe takes of those shots. If the shots are unclear or you propose a remake, offer a regenerate_keyframe note choice; existing takes stay in history. Report actual started keyframes, voice lines and price/quote for each scene, and explain per-scene refusal codes while other eligible scenes start. Reviews, review replies, automatic, read-only and discuss-only turns cannot start paid work. Stop halts unsent work; preserve request-owned holds and reconcile unknown tool outcomes before any retry. For requested video in ready scenes, record one scene-anchored note per scene with a confirm_video choice and reply when useful. Say: "Confirm in this chat or in Keyframes." Offering a choice in an editing or keyframe-review turn starts nothing and costs nothing. For video, "yes", "ok" or "go ahead" replies are not confirmation: point to the open confirm_video choice or offer a fresh one if stale or settled. Never claim work started until the application reports it. The first chat or workspace action settles the note; respect elsewhere resolutions. Read-only and automatic turns keep their current rules.' : 'Current application policy overrides historical skill guidance: Director audio tools save pending suggestions only. Only a human press may start paid speech or transcription. Do not publish paid audio through a plan or describe a suggestion as a running job.',
      ...(successor ? ['Read the current request’s owned audio attachment identities and audio_operations before preparing transcription. If an audio attachment was sent with this fresh human editing request and the person asks what it says or its line is needed, prepare_recording_transcription may start that exact priced owned transcription under this request. Report its actual outcome and price. Never automatically attach, adopt or accept its transcript. Other recordings and prepare_narration_speech remain pending suggestions for a human press. Reviews, review replies and read-only turns cannot start transcription. Music and other generation still require the person’s action. Do not publish paid audio through plan source or blindly resubmit an unknown outcome.'] : []),
      'Inventory the current request, supplied material, existing brief/scenes/shots, recordings and media before asking intake questions. Read paged scene/shot/narration context as needed; an overview count is not the full content.',
      'Start from the most complete usable material. Preserve supplied intent, scene order and stated constraints. Fill only missing work; never restart a settled brief interview or regenerate existing media just to follow a stage sequence.',
      'Ask only questions needed for the next useful task. Offer concise options and identify uncertain interpretations. Narration and visual planning can progress independently when their actual prerequisites permit it.',
      'Keep optional creative suggestions separate from the supplied interpretation. Do not apply unchosen improvements. For ordinary chat, use existing scope and validated prepare/apply contracts; for a supplied-material import, prepare only the creative draft and wait for human confirmation.',
      audioRequests ? 'Organize summaries by scene and name one useful next decision. A valid draft is not accepted audio, reviewed image/video generation or finished footage. After confirmation, continue only missing requested work using fresh context.' : 'Organize summaries by scene and name one useful next decision. A valid draft is not accepted narration, approved frames, paid permission or finished footage. After confirmation, continue only the missing work using fresh context.',
      'Read shot.narration when present: it is the human-selected mode, script and voice preference, not accepted audio. Preserve existing canonical audio and mappings for other shots. A personal voice choice requires a configured eligible voice and explicit recorded-voice consent; do not substitute a stock voice silently. An explicit no-narration shot with no cue uses its planned duration directly; do not create silent recordings or fake accepted cues. Undecided narration is a gap; generated/uploaded narration requires accepted measured audio. Preserve other shots’ accepted audio.',
      'A project soundtrack is an optional owned recording mixed at its saved gain by the application renderer. Music does not imply narration or a speech request. Do not generate replacement music or add it as a narration cue. Read the saved soundtrack choice when assembling.',
      successor ? "Drafting or editing the brief, story, scenes, shot cards and narration needs no generation review. Configured API keys and Codex installation enable the selected provider without another approval or usage allowance. A fresh human editing request for keyframes can start them and their needed voice lines through make_keyframes, with actual work and price reported. A current-request audio attachment can be transcribed when requested or needed; its transcript never attaches or accepts itself. The person reviews the current keyframes, motion, narration and actual video recipe, then clicks one scene confirmation in chat or Keyframes to start video. Listening and recording edits are optional; do not ask for a separate narration review. Video and other paid generation remain human actions." : audioRequests ? "Drafting or editing the brief, story, scenes, shot cards and narration needs no generation review. Configured API keys and Codex installation enable the selected provider without another approval or usage allowance. The human views the current keyframes, motion and narration, then uses one scene confirmation. The studio prepares and saves narration through authenticated shot operations and generates the reviewed video. Listening and recording edits are optional; do not ask for a separate narration review. Director audio tools only prepare pending suggestions; explicit human presses start speech and transcription through application routes. Do not ask the user to authorize narration guidance or spending." : "Drafting or editing the brief, story, scenes, shot cards and narration is ordinary project work and needs no media generation permission or spending approval. Do not ask the user to authorize writing guidance. Creating keyframe images or video operations requires exact generation permission; the human generation press is required and no spending allowance is needed. Say 'keyframe image generation' instead of 'storyboard generation authorization' when describing that blocker.",
      'Direct storyboard edits, narration edits, proposal decisions and note resolution run alongside the Director and retain existing epochs. HUMAN_EDITED_FIELD fences fields changed by a person since the turn context was captured. Typed new direction still interrupts. Resume from the current IDs and narration choices, preserving unchanged media. Recompile only affected work and obtain fresh generation authorization where required.',
      successor ? 'Writing needs no generation or spending permission. On shots with media, narration changes use propose_change and human preview acceptance. Without media impact, save narration writing directly through a creative patch. Preserve the selected shot scope and all other narration.' : toolVersion === '5.0.0' ? 'Writing needs no generation or spending permission. Narration changes use propose_change and human preview acceptance. A human edits the saved shot; do not apply narration changes directly or widen scope.' : toolVersion === '4.0.0' ? 'For a shot-scoped conversational script change, prepare_change may save creative.updateShots[].narration writing intent, with reauthorPrompts: true, then apply its prepared-change ID. An explicit mode=none clears its own cue through the application. Writing needs no generation or spending permission. Do not silently widen to the project-wide narration collection. The compact editor prioritizes that incoming writing and requires explicit recording/timing acceptance. App-derived narrationPending blocks video while new writing is unaccepted. Writing-only edits preserve the visual shot revision when its cue binding is unchanged; project revisions still fence every edit.' : 'This already-started conversation cannot write compact shot narration through its saved catalog. A fresh native conversation loads compatible current application guidance automatically; ask for a new message only if this turn needs unavailable shot-writing fields. The human may also edit the storyboard card directly. Writing needs no generation or spending permission. Do not submit unavailable fields or widen to a project-wide narration collection. Existing narration draft tools remain limited to their application-authorized narration scope.',
